 83	            if (sum == target) {
 84	                return SearchResult.match(left, right);
 85	            }
 86	
 87	            if (sum < target) {
 88	                left++;
 89	            } else {
 90	                right--;
 91	            }
 92	        }
 93	
 94	        return SearchResult.notFound();
 95	    }
