110	    private static void validateSorted(int[] values) {
111	        if (values == null) {
112	            throw new IllegalArgumentException("values must not be null");
113	        }
114	
115	        for (int index = 1; index < values.length; index++) {
116	            if (values[index - 1] > values[index]) {
117	                throw new IllegalArgumentException(
118	                    "two-pointer search requires values sorted in nondecreasing order");
119	            }
120	        }
